import{_ as A,l as i,o as e,c as o,v as t,p as n,x as l,d as s,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"RAG 评测 RAGAS","description":"","frontmatter":{"title":"RAG 评测 RAGAS","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-evaluation.md","filePath":"llm/rag-evaluation.md","lastUpdated":1789023840000}'),p={name:"llm/rag-evaluation.md"};function h(c,a,_,m,R,u){const r=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="rag-评测-ragas" tabindex="-1">RAG 评测 RAGAS <a class="header-anchor" href="#rag-评测-ragas" aria-label="Permalink to &quot;RAG 评测 RAGAS&quot;">​</a></h1><div class="epigraph"><p>端到端准确率把检索错误与阅读错误绑死。要把上下文相关性、忠实度、答案相关性分列，管道才能知道该改哪一段。</p><footer>—— Es 等 RAGAS；检索与生成必须分指标</footer></div><p><a href="/llm/citation-attribution">上一课</a>定义了支撑。工程上还要一套可回归的自动分，不必每夜都上人评。Es 等人的 RAGAS 把 RAG 拆成若干 LLM 辅助指标。缺口是读懂这些分测的是管道哪一段。后课自适应 RAG 默认：你已经能测「该不该检索」，而不是只看最终 BLEU。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有最终答案对错时，检索召回低与阅读器胡编可以分数相同。RAGAS 一类协议提出：忠实度（答案是否可由上下文推出）、答案相关性（是否在问所问）、上下文精度/召回（检索块相对需要的证据）。许多实现用 LLM 法官估这些量，于是继承<a href="/llm/llm-judge-bias">裁判偏差</a>：未校准前只能当烟雾。</p><p>金标可用时，检索用标准 IR 指标（nDCG、Recall@\\(k\\)），生成用支撑与精确匹配。无金标时，RAGAS 是代理，必须抽检。</p><p><span class="marginnote">「上下文召回」需要「该题应引用哪些块」的概念。没有题级证据标注时，这个量是法官的想象，方差大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小表：检索 Recall@\\(k\\) / nDCG（有金标块时）；忠实度；答案正确（有金标答时）；引用可解析率。RAGAS 分数与表并排，不替代。固定法官模型与提示版本。切片：无检索命中、有命中仍不忠、过检索（块对但答偏）。差异集派人看。</p>',9)),(e(),n(E,null,{default:l(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIPE%5B%22RAG%20%E7%AE%A1%E9%81%93%22%5D%20--%3E%20IR%5B%22%E6%A3%80%E7%B4%A2%20IR%20%E6%8C%87%E6%A0%87%22%5D%0A%20%20PIPE%20--%3E%20FAI%5B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%22%5D%0A%20%20PIPE%20--%3E%20ANS%5B%22%E7%AD%94%E6%A1%88%E6%AD%A3%E7%A1%AE%20%2F%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20IR%20--%3E%20DIAG%5B%22%E5%AE%9A%E4%BD%8D%E6%95%85%E9%9A%9C%E6%AE%B5%22%5D%0A%20%20FAI%20--%3E%20DIAG%0A%20%20ANS%20--%3E%20DIAG%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分列指标对应管道的条件依赖：检索差则阅读器无论多忠也会信息不足；检索好而忠实度低是阅读器或提示问题；二者都高而答案不相关是任务理解问题。把它们加总成单分会回到 MMLU 式平均。自适应课将用这些信号决定是否检索、是否再检索。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自动忠实度不是法律保证。下一课自适应 RAG：用信号在「直答 / 检索 / 再检索」之间路由。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAG 必须分列检索与忠实度，禁止只报端到端。</li><li>RAGAS 等 LLM 指标是代理，要校准与抽检。</li><li>有金标块时优先标准 IR 指标。</li><li>出处：Es 等 RAGAS；ALCE；IR 评测通识。</li></ul>',6))])}const f=A(p,[["render",h]]);export{S as __pageData,f as default};
